#!/usr/bin/env python3
"""Generate the source-bound obligations ledger; no proof status inferred from declarations."""
import json,hashlib
from pathlib import Path
R='reports/native-repair-20261013/'
def row(id,files,norm,evidence,obligations,scope='Scratch JavaScript implementation'):
 return dict(id=id,scope=scope,sources=[{'path':f,'sha256':hashlib.sha256(Path(f).read_bytes()).hexdigest()} for f in files],normative_sources=norm,evidence=evidence,formal_implementation_refinement='OPEN',obligations=obligations)
rows=[
row('SHA-2',['crypto/sha256.mjs','crypto/sha512.mjs'],['https://csrc.nist.gov/pubs/fips/180-4/upd1/final'],[R+'t_sha256.txt',R+'t_sha512.txt',R+'t_native_profile.txt'],['Compression function and padding refinement','Streaming/one-shot equivalence for arbitrary chunk boundaries','Length limits and counter overflow']),
row('Keccak / SHA-3 / SHAKE',['crypto/keccak.mjs'],['https://csrc.nist.gov/pubs/fips/202/final'],[R+'t_keccak.txt',R+'nist-acvp.json'],['Permutation round and lane-index refinement','Domain suffix and multi-rate padding correctness','XOF absorb/squeeze equivalence; SHA-3 is not raw Keccak']),
row('BLAKE2 / BLAKE3',['crypto/blake2.mjs','crypto/blake3.mjs'],['https://www.rfc-editor.org/rfc/rfc7693.html','https://github.com/BLAKE3-team/BLAKE3-specs'],[R+'t_blake2.txt',R+'t_blake3.txt'],['Counter, final-block and tree-combination refinement','Streaming equivalence and supported digest lengths']),
row('Ed25519 / local identity',['crypto/ed25519.mjs','crypto/aibom.mjs','agent/identity.mjs'],['https://www.rfc-editor.org/rfc/rfc8032.html'],[R+'t_ed25519.txt',R+'t_native_profile.txt',R+'surface.txt'],['Curve arithmetic, scalar reduction and encoding refinement','Canonical point and low-order rejection profile','Entropy and persistent key binding','Recorder signature does not prove source authorship or operator endorsement']),
row('ECDSA P-256/384/521',['crypto/ecdsa.mjs','crypto/der.mjs'],['https://www.rfc-editor.org/rfc/rfc6979.html','https://csrc.nist.gov/pubs/fips/186-5/final'],[R+'rfc6979.json',R+'t_ecdsa.txt',R+'t_native_profile.txt'],['Curve and group arithmetic refinement','RFC6979 curve-selected HMAC nonce derivation','DER/key validation and scalar bounds','Variable-time BigInt: no timing guarantee']),
row('RSA-PSS / SHA-256',['crypto/rsa-pss.mjs'],['https://www.rfc-editor.org/rfc/rfc8017.html'],[R+'t_native_profile.txt',R+'rsa-keygen.json',R+'html-audit.txt'],['PSS encoding, salt length and modulus-bit boundaries','Imported DER key validation','Probable-prime key generation, CRT and blinding correctness','Variable-time modular arithmetic']),
row('X25519 / relay envelope',['crypto/x25519.mjs','agent/envelope.mjs'],['https://www.rfc-editor.org/rfc/rfc7748.html'],[R+'surface.txt'],['Ladder refinement, clamping and input high-bit mask','All-zero shared-secret rejection','Composition with HKDF, AEAD and signed envelope','Legacy wire format compatibility']),
row('ML-KEM-512/768/1024',['crypto/mlkem.mjs'],['https://csrc.nist.gov/pubs/fips/203/final'],[R+'nist-acvp.json','vectors/nist-acvp/SOURCE_MANIFEST.json'],['NTT/polynomial arithmetic, sampling, compression and encoding refinement','Key input checks and implicit rejection','Encapsulation randomness and domain separation','Track normative errata and revision changes']),
row('ML-DSA-44/65/87',['crypto/mldsa.mjs'],['https://csrc.nist.gov/pubs/fips/204/final'],[R+'nist-acvp.json','vectors/nist-acvp/SOURCE_MANIFEST.json'],['NTT, hint/decomposition and rejection-sampling refinement','Pure/prehash/context/external-mu profiles remain explicit','Canonical signature encoding and bounds','Timing and randomness analysis']),
row('ChaCha20 / Poly1305 / AEAD',['crypto/chacha20-poly1305.mjs'],['https://www.rfc-editor.org/rfc/rfc8439.html'],[R+'t_native_profile.txt'],['Quarter-round and block-function refinement','Poly1305 clamp, arithmetic and reduction','AAD/ciphertext pad and length encoding','Key/nonce uniqueness and counter bounds','Authentication before plaintext release; timing analysis']),
row('AES-256 / GCM',['crypto/aes256-gcm.mjs'],['https://csrc.nist.gov/pubs/fips/197/final','https://csrc.nist.gov/pubs/sp/800/38/d/final'],[R+'t_native_profile.txt'],['S-box, AES key schedule and 14-round refinement','GHASH field representation and length encoding','96-bit nonce / 128-bit tag profile only','Nonce uniqueness, per-key bounds and authentication before release','Table/BigInt timing remains unproven']),
row('HKDF / encryption layers',['crypto/hkdf.mjs','crypto/hmac.mjs','crypto/vault-stream.mjs','src/browser-native.js'],['https://www.rfc-editor.org/rfc/rfc5869.html'],[R+'t_vault_stream.txt',R+'surface.txt'],['Canonical header binds algorithm, recipient, KEM ciphertext, salt and nonce as AAD','Signed outer encrypted receipt binds ciphertext; key encapsulation alone does not authenticate sender','KDF output/limit and protocol domain separation','PB-VAULT-1 custom SHAKE record KDF is not standardized HKDF','Streaming finalization, truncation, order and record reuse']),
row('Canonical JSON / commitments / receipts',['src/canonical/canonical-json.mjs','src/encoding/base64url.mjs'],['https://www.rfc-editor.org/rfc/rfc8785.html','https://www.rfc-editor.org/rfc/rfc6962.html'],[R+'surface.txt',R+'html-audit.txt'],['Hash UTF-8 bytes of canonical JSON; never hash a pretty-printed object interchangeably','Reject duplicates, lone surrogates, cycles, sparse arrays, undefined and non-finite numbers','Explicit ECMAScript numeric domain and UTF-16 property ordering','Bind profile and exclude only specified seal fields; Merkle domain separation','JavaScript serializer/parser refinement remains open']),
row('OpenTimestamps',['agent/ots.mjs'],['https://github.com/opentimestamps/opentimestamps-client'],[R+'surface.txt'],['Bind exact detached target bytes to .ots file','Calendar submission is not Bitcoin verification','Verify operation path, Bitcoin header Merkle root and chain evidence','Instrument success marker is an adapter contract; transcript text alone is not an anchor','RFC3161 response retention is unverified; CMS, imprint/nonce and certificate-chain verification are not implemented','No external timestamp was submitted or Bitcoin anchor established by this repair'],scope='Optional external verifier adapter; not a scratch Bitcoin verifier'),
row('File browser / custody',['src/browser-native.js'],['https://developer.mozilla.org/en-US/docs/Web/API/Window/showDirectoryPicker'],[R+'browser-workflows.json'],['Bounded read-only folder permission and preserved relative paths','Original file bytes remain unchanged','Persistent key and receipt continuity across reloads','Captured bytes, source attribution, declaration and verification are separate states'],scope='Browser permission and custody workflow'),
row('Falcon / SLH-DSA compatibility',['proofbundle.html'],['https://csrc.nist.gov/pubs/fips/205/final'],[R+'html-audit.txt'],['Bundled providers are not scratch implementations','Legacy algorithm names do not establish final-standard conformance','Full vector and implementation-refinement evidence required per exact profile'],scope='Bundled third-party compatibility providers; separate from native basis')]
# Avoid a circular self-hash for the HTML whose embedded ledger we generate.
for x in rows:
 if x['id'].startswith('Falcon'):x['sources']=[{'path':'proofbundle.html','binding':'Final shipped HTML hash in release receipt; not embedded recursively'}]
nist=json.loads(Path(R+'nist-acvp.json').read_text())
ledger={'schema':'ProofBundleCryptographicBasis/v1','basis_date':'2026-10-13','source_authority':'Normative specifications and pinned native vector files; generated narratives are derivatives','runtime':{'crypto_computation':'Scratch source modules embedded in HTML; compatibility providers explicitly identified','entropy':'OS crypto.getRandomValues only','standalone_requires_node':False,'optional_node':'Development runner and local transport/filesystem adapters'},'conformance':{'nist_sample_cases':sum(x['passed'] for x in nist['results']),'nist_failed':sum(x['failed'] for x in nist['results']),'receipt':R+'nist-acvp.json','certification':'No CAVP or FIPS module certification claimed'},'formal_basis':{'scope':'Eight abstract Lean interface/model theorems, all axiom-free in this audit; not JavaScript implementation refinement','audit':'lean/NativeBasisAudit.lean','receipt':R+'lean-native-basis-axioms.txt'},'profiles':rows}
Path('CRYPTOGRAPHIC_BASIS.json').write_text(json.dumps(ledger,indent=2)+'\n')
text='''# Cryptographic basis and proof obligations

The repaired standalone application performs digest, signature, KEM, key derivation and authenticated encryption computation in embedded source modules. It requires no Node runtime or cryptographic computation service. OS entropy remains `crypto.getRandomValues`; eliminating entropy is not a cryptographic substitution. Optional Node tools still perform transport, filesystem and development tasks. Falcon and SLH-DSA compatibility providers remain bundled third-party code and are separately identified.

## Ground truths and evidence scope

The normative specifications and pinned vector bytes are the external basis. Source files, their hashes, executable tests and exact results establish the current implementation record. A registry declaration is not execution evidence. An operator signature, a recorder signature, and a model-authored claim establish different attribution facts.

The [NIST receipt](reports/native-repair-20261013/nist-acvp.json) records 855 passing published sample cases with zero failures: ML-KEM key generation (75), encapsulation/decapsulation and input checks (165), ML-DSA key generation (75), signature generation (360), and verification (180). All three parameter sets are exercised. The [source manifest](vectors/nist-acvp/SOURCE_MANIFEST.json) pins upstream commit, URL, size and SHA-256. These results are conformance evidence, not CAVP validation or FIPS module certification.

[Six RFC 6979 signatures](reports/native-repair-20261013/rfc6979.json) match the published scalar values exactly. The native profile tests compare SHA-2 and both AEADs against an independent test-only platform implementation and check published RFC 8439, AES-256 and GCM vectors. Streaming hash and envelope interoperability checks have their own suite. Browser boot diagnostics are a separate instrument and are not a count of these cases.

The [Lean audit](lean/NativeBasisAudit.lean) reports eight abstract interface/model theorems without axiom dependencies. Its [actual output](reports/native-repair-20261013/lean-native-basis-axioms.txt) is retained. Those theorems do not prove refinement of the JavaScript primitives. The broader existing audit initially failed because the root module had not been built. After the complete build, all 84 declarations in that audit reported no axiom dependencies; both outputs are retained. Those declarations also include architecture and agent-policy models. A theorem about a policy definition does not establish operator adoption or runtime enforcement. No implementation-refinement claim is made.

## Commitments and encryption composition

Receipt commitments hash the UTF-8 bytes of the specified canonical JSON body. Canonicalization rejects duplicate keys on text input and rejects unsupported object values, lone surrogates, cycles, sparse arrays and non-finite numbers. RFC 8785 property ordering and the ECMAScript number domain remain explicit. Pretty printing is an interchange presentation and is never the commitment representation.

`PB-ENCRYPTED-1` encapsulates a recipient secret with ML-KEM, derives an AEAD key with HKDF-SHA-256, and authenticates the canonical header as AAD. The header binds the parameter set, cipher, KEM ciphertext, salt, nonce and recipient fingerprint. A signed `PB-INTEGRITY-1` outer receipt binds the encrypted envelope to its recorder. Opening checks that signature and then the AEAD tag before releasing plaintext. Public-key encapsulation alone is not sender authentication. The browser file workflow reads one file into memory; it does not promise arbitrary-size streaming.

`PB-VAULT-1` retains its existing streaming record format and custom SHAKE-based record KDF. That KDF is not relabelled as standardized HKDF. Compatibility, truncation/order detection and cryptographic composition need separate evidence. The relay's X25519/HKDF/ChaCha envelope retains its existing wire format and rejects an all-zero shared secret.

OTS submission means a calendar accepted a commitment. Displaying a block-height attestation is insufficient. The adapter requires detached target verification with successful Bitcoin attestation output; failure and silent zero exit remain unverified. This repair does not create or claim a new Bitcoin anchor. A browser signing key does not prove model identity, operator endorsement, or a prior spawn registration.

## Primitive-by-primitive obligations

Implementation refinement is **OPEN** for every primitive below. Variable-time JavaScript BigInt/table arithmetic has no established timing guarantee. Testing the same implementation against itself is not independent conformance evidence.

'''
for x in rows:
 text+='### '+x['id']+'\n\n'+x['scope']+'.\n\nSources: '+', '.join('['+y['path']+']('+y['path']+')' for y in x['sources'])+'.\n\nNormative basis: '+', '.join('['+u.split('/')[-1]+']('+u+')' for u in x['normative_sources'])+'.\n\nEvidence: '+(', '.join('['+e.split('/')[-1]+']('+e+')' for e in x['evidence']) if x['evidence'] else 'Workflow receipt to be produced separately; no result inferred')+'.\n\nNecessary obligations:\n\n'+''.join('- '+o+'.\n' for o in x['obligations'])+'\n'
text+='The [machine-readable ledger](CRYPTOGRAPHIC_BASIS.json) binds these entries to source hashes. The [embedded source manifest](CRYPTO_SOURCE_MANIFEST.json) records the native modules. A final release receipt must bind the complete shipped HTML and the tests performed against that exact artifact.\n'
Path('CRYPTOGRAPHIC_BASIS.md').write_text(text)
print('Generated',len(rows),'source-bound profiles')
